import csv

PATH = "gradebook.csv"
FIELDS = ["name", "score"]

def parse_score(text):
    try:
        score = int(text)
    except ValueError:
        return None
    if not 0 <= score <= 100:
        return None
    return score

def save_records(path, records):
    with open(path, "w", encoding="utf-8", newline="") as file:
        writer = csv.DictWriter(file, fieldnames=FIELDS)
        writer.writeheader()
        writer.writerows(records)

def load_records(path):
    try:
        with open(path, "r", encoding="utf-8", newline="") as file:
            reader = csv.DictReader(file)
            return [{"name": row["name"], "score": int(row["score"])} for row in reader]
    except FileNotFoundError:
        return []

def summarize(records):
    if not records:
        return {"count": 0, "average": None, "highest": None}
    scores = [record["score"] for record in records]
    return {"count": len(records), "average": sum(scores) / len(scores), "highest": max(scores)}

def main():
    n = max(0, int(input()))
    records = []
    for _ in range(n):
        name = input().strip()
        while True:
            score = parse_score(input())
            if score is not None:
                break
            print("Invalid score")
        records.append({"name": name, "score": score})

    save_records(PATH, records)
    result = summarize(load_records(PATH))
    print(f"Records: {result['count']}")
    if result["average"] is None:
        print("Average: N/A")
        print("Highest: N/A")
    else:
        print(f"Average: {result['average']:.2f}")
        print(f"Highest: {result['highest']}")

if __name__ == "__main__":
    main()
